#!/usr/bin/env node
// Publish photos: drop edited exports into incoming/<Category>/ and run `npm run photos`.
// Category comes from the folder name, caption from the filename
// (winter-stroll-in-japan.jpg -> "Winter Stroll In Japan"); thumbnail and
// lightbox sizes are generated by scripts/images.js.
const fs = require("fs");
const path = require("path");
const { GALLERY, ROOT, derive, readManifest, writeManifest } = require("./images");

const INCOMING = path.join(ROOT, "incoming");

if (!fs.existsSync(INCOMING)) {
  fs.mkdirSync(INCOMING, { recursive: true });
  console.log("Created incoming/ — drop photos into incoming/<Category>/ and rerun.");
  process.exit(0);
}

const manifest = readManifest();
const known = new Set(manifest.map((i) => i.file));

const titleCase = (slug) =>
  slug
    .replace(/[-_]+/g, " ")
    .trim()
    .replace(/\b\w/g, (c) => c.toUpperCase());

let added = 0;
let failed = 0;
for (const category of fs.readdirSync(INCOMING)) {
  const dir = path.join(INCOMING, category);
  if (!fs.statSync(dir).isDirectory()) continue;
  for (const file of fs.readdirSync(dir)) {
    if (!/\.(jpe?g|png|webp)$/i.test(file)) continue;
    if (known.has(file)) {
      console.warn(`skip (already in gallery): ${file}`);
      continue;
    }
    const from = path.join(dir, file);
    const to = path.join(GALLERY, file);
    fs.renameSync(from, to);
    let size;
    try {
      size = derive(file);
    } catch (err) {
      // leave nothing half-published: put the photo back and carry on
      fs.renameSync(to, from);
      failed++;
      console.error(`FAILED (left in incoming/${category}/): ${file} — ${err.message}`);
      continue;
    }
    manifest.push({
      file,
      caption: titleCase(file.replace(/\.[^.]+$/, "")),
      category,
      w: size.w,
      h: size.h,
    });
    // save after every photo so an interrupted run keeps what it finished
    writeManifest(manifest);
    known.add(file);
    added++;
    console.log(`added: ${file}  [${category}]`);
  }
}

if (failed) {
  console.error(`\n${failed} photo(s) could not be processed and were left in incoming/.`);
  process.exitCode = 1;
}
console.log(
  added
    ? `\n${added} photo(s) published. Preview locally, then: npm run deploy`
    : "Nothing to add — drop photos into incoming/<Category>/."
);
